head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Simple
Designer: Blogger
URL:      www.blogger.com
----------------------------------------------- */

/* Content
----------------------------------------------- */
body {
  font: normal normal 14px Arial, Tahoma, Helvetica, FreeSans, sans-serif;
  color: #222222;
  background: #66bbdd none repeat scroll top left;
  padding: 0 40px 40px 40px;
}
html body .region-inner {
  min-width: 0;
  max-width: 100%;
  width: auto;
}
h2 {
  font-size: 22px;
}
a:link {
  text-decoration:none;
  color: #2288bb;
}
a:visited {
  text-decoration:none;
  color: #888888;
}
a:hover {
  text-decoration:underline;
  color: #33aaff;
}
.body-fauxcolumn-outer .fauxcolumn-inner {
  background: transparent url(https://resources.blogblog.com/blogblog/data/1kt/simple/body_gradient_tile_light.png) repeat scroll top left;
}
.body-fauxcolumn-outer .cap-top {
  position: absolute;
  z-index: 1;
  height: 400px;
  width: 100%;
}
.body-fauxcolumn-outer .cap-top .cap-left {
  width: 100%;
  background: transparent url(https://resources.blogblog.com/blogblog/data/1kt/simple/gradients_light.png) repeat-x scroll top left;
}
.content-outer {
  box-shadow: 0 0 40px rgba(0, 0, 0, .15);
  margin-bottom: 1px;
}
.content-inner {
  padding: 10px 10px;
  background-color: #ffffff;
}

/* Header
----------------------------------------------- */
.header-outer {
  background: transparent none repeat-x scroll 0 -400px;
}
.Header h1 {
  font: normal normal 48px Arial, Tahoma, Helvetica, FreeSans, sans-serif;
  color: #3399bb;
  text-shadow: -1px -1px 1px rgba(0, 0, 0, .2);
}
.Header h1 a {
  color: #3399bb;
}
.Header .description {
  font-size: 140%;
  color: #777777;
}
.header-inner .Header .titlewrapper {
  padding: 22px 30px;
}
.header-inner .Header .descriptionwrapper {
  padding: 0 30px;
}

/* Columns
----------------------------------------------- */
.main-inner {
  padding-top: 30px;
  padding-bottom: 30px;
}
.main-inner .column-center-inner {
  padding: 0 15px;
}
.main-inner .column-center-inner .section {
  margin: 0 15px;
}
.post {
  margin: 0 0 25px 0;
}
h3.post-title, .comments h4 {
  font: normal normal 22px Arial, Tahoma, Helvetica, FreeSans, sans-serif;
  margin: .75em 0 0;
}
.post-body {
  font-size: 110%;
  line-height: 1.4;
  position: relative;
}

/* Headings & Sidebar
----------------------------------------------- */
div.widget > h2,
div.widget h2.title {
  margin: 0 0 1em 0;
  font: normal bold 11px Arial, Tahoma, Helvetica, FreeSans, sans-serif;
  color: #000000;
}

/* Remove leftover sidebar widget titles and mobile chrome */
#HTML1 .title,
#HTML2 .title,
#HTML3 .title,
.sidebar .widget.HTML .title,
.foot .widget.HTML .title,
.date-header,
.mobile .header-outer,
.mobile .Header,
.mobile .tabs-outer,
.mobile .date-header,
.mobile h3.post-title,
.mobile .post-header,
.mobile .post-footer,
.mobile .footer-outer,
.mobile .blog-pager {
  display: none !important;
}

/* ==========================================================================
   GLOBAL SAFETY & MOBILE RESPONSIVENESS OVERRIDES
   ========================================================================== */
img, iframe, video, table {
  max-width: 100%;
  height: auto;
}

body, .post-body, .fest-wrapper, .entry-content, p, h1, h2, h3, h4, h5, h6 {
  overflow-wrap: break-word;
  word-wrap: break-word;
}

@media screen and (max-width: 1279px) {
  body, body.mobile, body.variant-simplysimple, body.variant-pale {
    min-width: 0 !important;
    padding: 0 8px 16px 8px !important;
  }
  .content-outer,
  .content-fauxcolumn-outer,
  .region-inner,
  .main-inner,
  .columns-inner,
  .header-inner,
  .tabs-inner,
  .footer-inner,
  .mobile .content-outer,
  .mobile .region-inner,
  .mobile .main-inner,
  .mobile .columns,
  .mobile .column-center-outer,
  .mobile .post-outer,
  .mobile .post-body {
    min-width: 0 !important;
    max-width: 100% !important;
    width: 100% !important;
    box-sizing: border-box !important;
  }
  .content-inner {
    padding: 8px 6px !important;
  }
  .Header h1 {
    font-size: 32px !important;
  }
  .main-inner {
    padding-top: 10px !important;
    padding-bottom: 15px !important;
  }
  .main-inner .columns,
  .main-inner .columns-inner {
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
  .main-inner .column-center-outer {
    width: 100% !important;
    float: none !important;
    margin: 0 !important;
  }
  .main-inner .column-center-inner,
  .main-inner .column-center-inner .section {
    padding: 0 !important;
    margin: 0 !important;
  }
  .main-inner .column-right-outer {
    width: 100% !important;
    float: none !important;
    margin: 24px auto 0 !important;
    clear: both !important;
  }
  .main-inner .fauxcolumn-center-outer,
  .main-inner .fauxcolumn-right-outer,
  .main-inner .fauxcolumn-left-outer {
    display: none !important;
  }
  .section-columns td.columns-cell {
    display: block !important;
    width: 100% !important;
    border-left: none !important;
    box-sizing: border-box !important;
  }
}

@media screen and (min-width: 1280px) {
  body {
    padding: 0 40px 40px 40px;
  }
  .content-outer,
  .content-fauxcolumn-outer,
  .region-inner {
    max-width: 1100px;
    width: 1100px;
    margin: 0 auto;
  }
  .main-inner .columns {
    padding-left: 0;
    padding-right: 310px;
  }
  .main-inner .column-right-outer {
    width: 310px;
    margin-right: -310px;
  }
}

head.b:template-skin:
body {
  min-width: 0;
}
.content-outer, .content-fauxcolumn-outer, .region-inner {
  min-width: 0;
  max-width: 100%;
  width: auto;
}
